#include <limits>
int main() {
    std::fesetround(FE_TONEAREST);
    backend::CpuBackend cpu;
    uint32_t state=12345;
    auto next=[&](){state=state*1664525u+1013904223u;return float(int(state>>8)-8388608)/8388608.0f;};
    size_t values_checked=0,outputs_checked=0;
    for(size_t nb: {size_t(1),size_t(3),size_t(7),size_t(32)}) {
        const size_t rows=49;
        std::vector<float> x(nb*32), scales(nb), expected(rows), out(rows);
        std::vector<int> quantized(nb*32);
        std::vector<uint8_t> weights(rows*nb*34);
        for(int kind=0;kind<4;++kind) {
            for(auto& v:x) v=kind==0?0.0f:kind==1?next()*13.0f:kind==2?127.0f:-127.0f;
            if(!cpu.pack_q8_activation(x.data(),nb)) return 2;
            for(size_t b=0;b<nb;++b) {
                float maximum=0;for(size_t j=0;j<32;++j)maximum=std::max(maximum,std::fabs(x[b*32+j]));
                scales[b]=maximum/float((1<<(ACT_BITS-1))-1);
                float inv=scales[b]>0?1.0f/scales[b]:0;
                if(std::memcmp(&scales[b],&cpu.q8_scales_[b],4)) return 3;
                for(size_t j=0;j<32;++j) {
                    quantized[b*32+j]=int(std::nearbyint(x[b*32+j]*inv));
#if ACT_BITS == 16
                    const int actual=cpu.q16_values_[b*32+j];
#else
                    const int actual=cpu.q8_values_[b*32+j];
#endif
                    if(actual!=quantized[b*32+j]) return 4;
                    ++values_checked;
                }
            }
            for(size_t row=0;row<rows;++row) {
                float lanes[8]={};
                for(size_t b=0;b<nb;++b) {
                    uint8_t* w=weights.data()+(row*nb+b)*34;
                    const uint16_t cases[]={0x0001,0x0400,0x3800,0x3c00,0x8001};
                    uint16_t h=cases[(row+b)%5];w[0]=uint8_t(h);w[1]=uint8_t(h>>8);
                    for(size_t j=0;j<32;++j) w[2+j]=uint8_t((row*13+b*7+j*19)&255);
                    if(kind>=2)for(size_t j=0;j<32;++j)w[2+j]=128;
                    float scale=f16_to_f32(h)*scales[b];
                    for(size_t lane=0;lane<8;++lane) {
                        int sum=0;
                        for(size_t t=0;t<4;++t) {
#if ACT_BITS == 16
                            size_t j=2*lane+(t&1)+(t/2)*16;
#else
                            size_t j=4*lane+t;
#endif
                            sum+=int(int8_t(w[2+j]))*quantized[b*32+j];
                        }
                        lanes[lane]=std::fma(float(sum),scale,lanes[lane]);
                    }
                }
                float a=lanes[0]+lanes[4],b=lanes[1]+lanes[5],c=lanes[2]+lanes[6],d=lanes[3]+lanes[7];
                expected[row]=(a+b)+(c+d);
            }
            for(int nt:{1,4,6}) {
                cpu.set_threads(nt);cpu.matvec_q8_0(weights.data(),x.data(),out.data(),nb,rows);
                for(size_t row=0;row<rows;++row) {
                    if(std::memcmp(&expected[row],&out[row],4)) {std::cerr<<"dot mismatch "<<ACT_BITS<<" "<<nb<<" "<<kind<<" "<<row<<"\n";return 5;}
